import{z as n,x as p,o as t,c as m,q as l,j as r,D as e,d as o,s as i,S as B}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"相干长度与光源带宽预备","description":"","frontmatter":{"title":"相干长度与光源带宽预备","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/coherence-length-prep.md","filePath":"litho/coherence-length-prep.md","lastUpdated":1791063341000}'),d={name:"litho/coherence-length-prep.md"};function s(c,a,A,h,_,D){const E=p("Mermaid");return t(),m("div",null,[a[2]||(a[2]=l('<h1 id="相干长度与光源带宽预备" tabindex="-1">相干长度与光源带宽预备 <a class="header-anchor" href="#相干长度与光源带宽预备" aria-label="Permalink to &quot;相干长度与光源带宽预备&quot;">​</a></h1><div class="epigraph"><p>有限谱宽的光源，不同波长的相位随传播逐渐错开；时间相干长度与带宽近似成反比，单色平面波是零阶极限。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 第 10 章部分相干与 Hecht, Optics 的整理</footer></div><p><a href="/litho/photometry-etendue-prep">上一课</a>建立了亮度与 étendue。本课不重写功率守恒。缺口是：<a href="/litho/plane-wave-k">平面波与波矢</a> 里的时谐场 \\(e^{-i\\omega t}\\) 隐含无限相干时间——真实光源有线宽 \\(\\Delta\\lambda\\)，多长的光程差内干涉条纹还在？后课部分相干成像与色差都默认相干长度 \\(L_c\\) 是已知概念。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>准分子激光与等离子体源都有有限 \\(\\Delta\\lambda\\)。两束光的光程差 \\(\\Delta L\\) 超过 \\(L_c\\) 时，不同波长的相位关系被洗掉，干涉项减弱。<a href="/litho/thin-film-interference">薄膜干涉</a> 的条纹、胶层驻波，都对这条差敏感。没有 \\(L_c\\sim\\lambda^2/\\Delta\\lambda\\)，无法解释为何要把曝光谱压窄，也无法解释为何镜头色差必须在窄带内优化。缺口是时间相干的预备，不是再算一遍照度。</p><h3 id="时间相干不是空间相干" tabindex="-1">时间相干不是空间相干 <a class="header-anchor" href="#时间相干不是空间相干" aria-label="Permalink to &quot;时间相干不是空间相干&quot;">​</a></h3><p>时间相干由谱宽决定：同一点、不同时刻（或同一束、不同光程）的相关。空间相干由源的横向尺寸与观察距离决定：源面上不同点发出的光能否仍干涉。照明在光瞳上填得越满，空间相干往往越低。本课把 \\(L_c\\) 钉死，空间相干只点名；完整互相干函数是后课成像主线的题目。</p><p><span class="marginnote">高斯型谱的经验式 \\(L_c\\approx\\lambda^2/\\Delta\\lambda\\)。\\(\\Delta\\lambda\\) 用 FWHM 时系数会变，数量级不变。空间相干的经典定理是 Van Cittert–Zernike，本课不证。</span></p><p><span class="marginnote">术语翻译：相干长度就是&quot;干涉还成立的最大的光程差预算&quot;——两束光走岔的路一旦超过它，各波长的相位各自错开、亮暗条纹互相抹平，\\(|\\gamma|\\) 掉到接近零。它不是光&quot;跑了多远&quot;，而是&quot;岔开多少路之内还能打架&quot;。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>中心波长 \\(\\lambda\\)、谱宽 \\(\\Delta\\lambda\\)，相干长度 \\(L_c\\approx\\lambda^2/\\Delta\\lambda\\)。当 \\(\\Delta L\\gtrsim L_c\\)，复相干度 \\(|\\gamma|\\) 下降，干涉对比度掉。窄线宽激光 \\(L_c\\) 可以很长；准分子经线窄化后 \\(L_c\\) 仍常大于典型薄膜腔长，单色模型才够用。宽带灯 \\(L_c\\) 只有微米量级，只在近零光程差看见条纹。</p><p>色差：\\(n=n(\\lambda)\\) 使不同颜色的焦距不同，与 <a href="/litho/geometric-aberration-tour">几何像差一览</a> 的单色 Seidel 并列限制焦深。压窄 \\(\\Delta\\lambda\\) 同时服务相干与色差，但可能与上一课的通量打架。</p>',12)),(t(),r(B,null,{default:e(()=>[i(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BW%5B%22%E8%B0%B1%E5%AE%BD%20%CE%94%CE%BB%22%5D%20--%3E%20LC%5B%22%E7%9B%B8%E5%B9%B2%E9%95%BF%E5%BA%A6%20L_c%22%5D%0A%20%20LC%20--%3E%20OPD%5B%22%E5%85%89%E7%A8%8B%E5%B7%AE%20%CE%94L%22%5D%0A%20%20OPD%20--%3E%20VIS%5B%22%E5%B9%B2%E6%B6%89%E5%AF%B9%E6%AF%94%E5%BA%A6%22%5D%0A%20%20VIS%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%E6%88%90%E5%83%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p><span class="marginnote">数字实例：\\(193\\ \\mathrm{nm}\\) 光刻源经线窄化到 \\(\\Delta\\lambda \\approx 1\\ \\mathrm{pm}\\) 时，\\(L_c \\approx \\lambda^2/\\Delta\\lambda \\approx 3.7\\ \\mathrm{cm}\\)，比任何薄膜腔长都长，单色模型够用；而白炽灯 \\(\\Delta\\lambda\\) 在百纳米量级，\\(L_c\\) 只剩几微米——两者相差七个数量级。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>部分相干成像是时间相干与空间相干的乘积效应。光瞳填充（常用 \\(\\sigma\\) 描述）小则空间相干高、对比度好，但 étendue 利用差、剂量吃紧。\\(\\sigma\\) 大则相反。工艺在对比度与通量之间折中，本课不给出一次解完的配方。</p><p>本课程下一课 <a href="/litho/scalar-diffraction-bound">标量衍射的适用边界</a> 收束建模层次：标量 \\(U\\) 已经默认单色或窄带、偏振可平均。带宽过宽时，连「一个 \\(U\\)」都只是对谱的积分；那是后课，本课先保证你知道积分核会掉对比度。</p><p>时间相干还约束薄膜腔：胶层或抗反射层的往返光程必须远小于 \\(L_c\\)，单色干涉公式才直接可用。否则 \\(R(\\lambda)\\) 要在谱上积分，振荡被抹平。线窄化因此既是镜头色差的需求，也是薄膜对比度的需求。空间相干则决定掩模不同开口之间能否稳定干涉，那是成像主线的部分相干，本课只留名字。</p><p><span class="marginnote">常见误区：初学者容易以为&quot;相干性越强成像越好&quot;。实际上空间相干过强（光瞳填得很空、\\(\\sigma\\) 很小）会让剂量吃紧、光强利用率变差；时间相干够用就行，过长没有额外收益。两种相干要分开谈，别混成一个&quot;越好&quot;。</span></p>',6)),(t(),r(B,null,{default:e(()=>[i(E,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20TC%5B%22%E6%97%B6%E9%97%B4%E7%9B%B8%E5%B9%B2%22%5D%20--%3E%20WHY1%5B%22%E7%94%B1%E8%B0%81%E5%AE%9A%EF%BC%9A%E8%B0%B1%E5%AE%BD%20%CE%94%CE%BB%22%5D%0A%20%20TC%20--%3E%20WHAT1%5B%22%E7%BA%A6%E6%9D%9F%E4%BB%80%E4%B9%88%EF%BC%9A%E5%85%89%E7%A8%8B%E5%B7%AE%20%2F%20%E8%96%84%E8%86%9C%E8%85%94%E6%9D%A1%E7%BA%B9%22%5D%0A%20%20SC%5B%22%E7%A9%BA%E9%97%B4%E7%9B%B8%E5%B9%B2%22%5D%20--%3E%20WHY2%5B%22%E7%94%B1%E8%B0%81%E5%AE%9A%EF%BC%9A%E6%BA%90%E5%B0%BA%E5%AF%B8%E4%B8%8E%E5%85%89%E7%9E%B3%E5%A1%AB%E5%85%85%20%CF%83%22%5D%0A%20%20SC%20--%3E%20WHAT2%5B%22%E7%BA%A6%E6%9D%9F%E4%BB%80%E4%B9%88%EF%BC%9A%E6%8E%A9%E6%A8%A1%E5%BC%80%E5%8F%A3%E9%97%B4%E8%83%BD%E5%90%A6%E7%A8%B3%E5%AE%9A%E5%B9%B2%E6%B6%89%22%5D%0A%20%20WHY1%20--%3E%20FUT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%E6%88%90%E5%83%8F%22%5D%0A%20%20WHY2%20--%3E%20FUT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开互相干函数测量，不证 Van Cittert–Zernike。也不把 \\(L_c\\) 写进 CD 公式：中心波长进衍射，带宽通过对比度与色差间接进入工艺窗口。Fourier 光学的严格处理留给后一课程；本课只预备 \\(L_c\\) 与 \\(\\Delta\\lambda\\)。</p><p>后课默认：单色是窄带极限；\\(L_c\\sim\\lambda^2/\\Delta\\lambda\\)；光程差超过 \\(L_c\\) 则干涉不可靠。下一课问标量 \\(U\\) 何时必须退回矢量麦克斯韦。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限带宽给出时间相干长度 \\(L_c\\sim\\lambda^2/\\Delta\\lambda\\)。</li><li>光程差超过 \\(L_c\\)，干涉对比度下降；光刻源尽量窄带。</li><li>时间相干 ≠ 空间相干；后者与源尺寸、光瞳填充有关。</li><li>窄带同时缓解色差，可能牺牲通量。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Hecht, <em>Optics</em>。</li></ul>',5))])}const f=n(d,[["render",s]]);export{b as __pageData,f as default};
